//! Color conversions, re-implemented from the observable behavior of the
//! C++ `ColorSpace::ColorConverter` static methods.
//!
//! Every operation is performed in `f32` with the same operand order and
//! association as the original, so results are bit-for-bit identical.

use crate::color::{clamp, HSL, RGB};

/// C++ `std::max(a, b)` is `(a < b) ? b : a` (comparison-based, keeps `a`
/// on ties/NaN), unlike `f32::max`.
fn std_max(a: f32, b: f32) -> f32 {
    if a < b {
        b
    } else {
        a
    }
}

/// C++ `std::min(a, b)` is `(b < a) ? b : a`.
fn std_min(a: f32, b: f32) -> f32 {
    if b < a {
        b
    } else {
        a
    }
}

pub struct ColorConverter;

impl ColorConverter {
    /// RGB -> HSL. Hue is returned in degrees (0..360), matching the
    /// original which computes `h = 360.0f * (h / 6.0f)`.
    pub fn rgb_to_hsl(rgb: &RGB) -> HSL {
        let r = rgb.r;
        let g = rgb.g;
        let b = rgb.b;

        let max = std_max(std_max(r, g), b);
        let min = std_min(std_min(r, g), b);
        let l = (max + min) / 2.0;

        let mut h: f32 = 0.0;
        let mut s: f32 = 0.0;

        if max != min {
            let d = max - min;
            s = if l > 0.5 {
                d / ((2.0 - max) - min)
            } else {
                d / (max + min)
            };

            if r == max {
                h = (g - b) / d + if b > g { 6.0 } else { 0.0 };
            } else if g == max {
                h = 2.0 + (b - r) / d;
            } else {
                h = 4.0 + (r - g) / d;
            }
            h = 360.0 * (h / 6.0);
        }

        HSL::new(h, s, l)
    }

    /// HSL -> RGB. Hue is expected in degrees and normalized via `h / 360`.
    pub fn hsl_to_rgb(hsl: &HSL) -> RGB {
        let h = hsl.h / 360.0;
        let s = hsl.s;
        let l = hsl.l;

        if s == 0.0 {
            return RGB::new(l, l, l);
        }

        let q = if l < 0.5 { (1.0 + s) * l } else { (l + s) - l * s };
        let p = (l + l) - q;

        fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
            if t < 0.0 {
                t = 1.0 + t;
            }
            if t > 1.0 {
                t -= 1.0;
            }
            if t < 1.0 / 6.0 {
                return p + (6.0 * (q - p)) * t;
            }
            if t < 0.5 {
                return q;
            }
            if t < 2.0 / 3.0 {
                return p + 6.0 * ((q - p) * (2.0 / 3.0 - t));
            }
            p
        }

        let r = hue_to_rgb(p, q, h + 1.0 / 3.0);
        let g = hue_to_rgb(p, q, h);
        let b = hue_to_rgb(p, q, h - 1.0 / 3.0);

        RGB::new(r, g, b)
    }

    /// Scale the HSL saturation by `value`, clamped to [0, 1].
    pub fn adjust_saturation(color: &RGB, value: f32) -> RGB {
        let mut hsl = Self::rgb_to_hsl(color);
        hsl.s = clamp(hsl.s * value, 0.0, 1.0);
        Self::hsl_to_rgb(&hsl)
    }
}

