//! Formatting of floats exactly as C++ `std::cout << float` does by default:
//! the float is promoted to double and printed like `printf("%g", v)` with
//! the default precision of 6 significant digits.

/// Format an `f32` the way `std::ostream::operator<<(float)` does with
/// default flags (defaultfloat, precision 6, no showpoint).
pub fn format_g(value: f32) -> String {
    let v = value as f64; // exact promotion, like C++'s cvtss2sd

    if v.is_nan() {
        return if v.is_sign_negative() { "-nan".into() } else { "nan".into() };
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf".into() } else { "inf".into() };
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0".into() } else { "0".into() };
    }

    let neg = v < 0.0;
    let a = v.abs();

    // Round to 6 significant digits via exponential formatting; this yields
    // the same decimal rounding %g performs.
    let sci = format!("{:.5e}", a); // e.g. "3.57628e-7"
    let (mantissa, exp_str) = sci.split_once('e').unwrap();
    let exp: i32 = exp_str.parse().unwrap();
    let digits: String = mantissa.chars().filter(|c| c.is_ascii_digit()).collect();
    debug_assert_eq!(digits.len(), 6);

    let body = if exp < -4 || exp >= 6 {
        // Scientific notation: strip trailing zeros from the mantissa,
        // exponent is signed and at least two digits (e.g. "1e+06", "3.57628e-07").
        let mut m = String::new();
        m.push(digits.as_bytes()[0] as char);
        let frac = digits[1..].trim_end_matches('0');
        if !frac.is_empty() {
            m.push('.');
            m.push_str(frac);
        }
        format!("{}e{}{:02}", m, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else if exp >= 0 {
        // Fixed notation with all significant digits left of the point.
        let int_part = &digits[..=exp as usize];
        let frac = digits[exp as usize + 1..].trim_end_matches('0');
        if frac.is_empty() {
            int_part.to_string()
        } else {
            format!("{}.{}", int_part, frac)
        }
    } else {
        // Fixed notation, value < 1: leading zeros after the point.
        let zeros = "0".repeat((-exp - 1) as usize);
        let frac = format!("{}{}", zeros, digits);
        format!("0.{}", frac.trim_end_matches('0'))
    };

    if neg {
        format!("-{}", body)
    } else {
        body
    }
}

